          "html": "<p>诉讼最适合解决<strong class=\"key\">能够被法院判决、并且有证据证明的具体权利义务</strong>。如果你的目标只是让对方道歉、曝光或“给个说法”，但没有清楚的金钱、履行、停止行为等请求，诉讼成本和结果可能不匹配。</p>"
