          "html": "<p>人民法院可以通过诉讼平台在线完成立案、证据交换、庭审等环节。<strong class=\"key\">互联网法院目前是北京、杭州、广州三家特定法院</strong>，集中管辖范围由司法解释明确。自 2025 年 11 月 1 日起，主要聚焦网络数据、个人信息/隐私、虚拟财产、网络不正当竞争、域名、网络购物、全程在线网络服务等特定网络纠纷。</p>"
