  "discussion": {
    "title": "常见旅游骗局",
    "intro": "大皇宫“关闭”、20 铢 tuk-tuk、DCC、租车损坏索赔和宝石套利，是游客更常遇到的几类套路；下面分别给对应动作。",
    "html": "<ol><li><strong>“Grand Palace 今天关闭”</strong><p>景点附近有人声称大皇宫当天关闭，再主动安排 tuk-tuk，把你带去宝石店、裁缝店等购物点。</p><small><b>对策：</b>直接到官方入口核验，或查大皇宫官网开放信息；不要因为陌生人一句话临时改行程。</small></li><li><strong>“20 泰铢 tuk-tuk 城市游”</strong><p>异常低价常靠购物点回扣补贴车费，司机途中加入宝石店、裁缝店等停靠点。</p><small><b>对策：</b>优先使用 Grab、Bolt、正规出租车；上车前谈清直达目的地和价格，拒绝临时购物站。</small></li><li><strong>ATM / 刷卡机 DCC</strong><p>机器或商户让你直接用人民币等持卡人本币结算。DCC 是可选换汇服务，但常包含额外加价，汇率也未必划算。</p><small><b>对策：</b>默认拒绝 DCC，选择以泰铢（THB）结算；只有明确比较过汇率和费用后再考虑本币结算。</small></li><li><strong>摩托 / 水上摩托“损坏索赔”</strong><p>还车时被指认车辆已有划痕或损坏，并以押金甚至护照施压。</p><small><b>对策：</b>取车时连续拍摄车身、仪表和已有损伤；合同写清损伤和押金；不要把护照原件作为租赁抵押。</small></li><li><strong>“免税宝石投资 / 回国转卖赚钱”</strong><p>以稀缺、免税、可高价转卖为理由推动购买宝石，常与 tuk-tuk、导游或陌生人带店组合出现。</p><small><b>对策：</b>把“稳赚套利”直接视为红旗，不在陌生人带去的店里做投资型购买。</small></li></ol>"
  },
