  "route": {
    "title": "先书面谈方案和补偿；<br>协商不成再调解、仲裁或监察分流。",
    "steps": [
      {
        "title": "第一次约谈<br>听公司把理由说完",
        "text": "全程录音。问清是协商解除、严重违纪、不能胜任、调岗还是经济性裁员；把方案带走看。现场可以签“收到”，不要把“收到材料”写成“同意解除”。",
        "href": "#cases",
        "link": "回看对应场景 →"
      },
      {
        "title": "当天书面确认<br>把口头方案钉住",
        "text": "给HR和直属负责人发事实确认：公司提出什么、依据什么、工作安排有什么变化、你是否同意、你愿意继续履职。涉及额外奖励、补贴或背调承诺，也要求写入书面方案。",
        "href": "#template",
        "link": "复制书面确认 →"
      },
      {
        "title": "协商不成<br>用调解继续谈",
        "text": "把合同、约谈录音、工作量 / 调岗 / PIP / 警告、考勤、工资和自己的结算表带齐，与HR、工会或企业劳动争议调解组织继续谈；也可使用全国劳动人事争议在线调解服务平台。",
        "href": "https://tiaojie.12333.gov.cn/portal",
        "link": "全国在线调解 →"
      },
      {
        "title": "最后再升级<br>仲裁 / 劳动监察分流",
        "text": "解除是否合法、应否支付经济补偿或赔偿、是否继续履行等争议，通常进入劳动仲裁；一般仲裁时效为知道或应当知道权利受侵害之日起一年。欠薪、未依法出具解除证明等涉嫌违反劳动保障法律法规的事项，可同时咨询属地人社部门或12333。程序时间可能很长，所以更要在解除前把证据链做完整。",
        "href": "https://www.12333.gov.cn/",
        "link": "全国人社政务服务 →"
      }
    ],
    "note": "<strong>仲裁可能持续数月。</strong>第一次约谈录音、考勤、绩效原始数据、工作量变化、调岗 / PIP / 警告和解除通知现在就保存，不要等劳动关系已经解除后再补。",
    "intro": "第一次约谈先听清解除理由并留录音；当天把口头方案转成书面确认。还能谈就继续协商或调解，解除和补偿争议最后再进入仲裁，欠薪等事项另按人社监察渠道处理。"
  },
  "template": {
    "label": "第一次裁员约谈后的书面确认",
    "title": "把第一次约谈，<br>转成一封书面记录。",
    "intro": "目的：固定谁提出解除、公司准备采用什么理由、工作条件发生了什么变化，以及你仍然愿意正常履职。按实际情况删改。",
    "text": "主题：关于今日劳动关系沟通事项的书面确认\n\n我于____年__月__日收到公司关于【协商解除 / 调岗 / PIP / 纪律处理 / 裁员】的沟通。为避免双方理解出现偏差，请公司书面说明以下事项：\n\n1. 本次是否由公司提出解除劳动合同；如拟解除，请说明拟采用的事实理由、解除依据和解除日期；\n2. 如调整岗位、工作地点、工作量、工时或薪酬，请说明调整后的具体内容、期限、考核标准及相应依据；\n3. 如公司主张我不能胜任工作，请提供对应岗位标准、绩效原始数据，以及培训或调岗安排；\n4. 如公司主张我存在违纪，请说明具体行为发生时间、证据、对应制度条款、制度公示 / 签收记录及此前处理情况；\n5. 请提供结算方案，包括截至解除日应发工资、经济补偿 / 赔偿项目、计算基数、支付日期，以及今日沟通中公司承诺的其他补贴 / 奖励（如有）。\n\n在双方尚未形成书面一致意见前，我不提交“个人原因辞职”申请。我愿继续按照劳动合同正常提供劳动，请公司明确后续报到地点、工作任务及必要的系统 / 设备权限。\n\n如上述记录与公司理解不一致，请书面回复更正。"
  },
  "discussion": {
    "title": "案例参考｜星宇股份：从“离职 / 产线二选一”到公开致歉",
    "html": "<p><strong>2026年夏天，星宇股份共招录440名高校毕业生。</strong>多名新员工向媒体称，8月8日起陆续被集中约谈，HR以“公司经营出现一些状况”“组织架构调整、岗位缩编”等理由，给出<strong>离职或调至生产操作岗位</strong>的选择；有受访者称，离职方案一度为半个月工资补偿，调岗则意味着岗位内容、薪酬和工作时长随生产岗位调整。8月25日，常州市人社局官方通报确认：440人中有107人解除劳动合同，企业在协商过程中“方法简单生硬，缺乏充分有效沟通”，并已对人力资源总监作出停职处理。</p><p>凤凰网科技采访的一名前员工“林喆”（化名）还称，他在职期间每到春节前用工紧张时，公司会安排部分管理岗、研发岗、行政岗人员去产线顶岗，产线工作结束后原岗位事务仍需继续处理；他还称自己最长一次曾连续工作<strong>24至26小时</strong>。<strong>这些属于前员工个人陈述，尚未见监管部门逐项核实，不能直接当成已经认定的违法事实或裁判结论。</strong>它们真正补强了一个判断：公司提出“调岗”时，岗位名称远远不够，必须把职责、班次、工时、薪酬、原岗位任务是否继续承担一起问清。</p><p>8月27日，星宇股份公开致歉，承认“由于公司的原因”致107位同学离开，并宣布发放3个月求职生活补贴、期间免费住宿和岗位推荐；如11月底前仍未实现单位就业，再给予6个月工资作为补偿。<strong>如果公司先谈离职，随后又改成调岗、绩效或纪律处理，最初约谈的录音、解除理由、调岗内容、工时和补偿方案就成为后续核对的起点。</strong></p>",
    "intro": "星宇股份事件没有给出通用补偿数字。它说明：公司从“协商离职”转向调岗、绩效或纪律路径时，第一场约谈和后续条件变化必须放在同一条时间线上核对。"
  },
