  "legal": "免责声明：本页提供中国大陆一般劳动合同解除争议的行动框架，不替代针对具体劳动合同、地方工资口径、工会程序、特殊保护身份和案件证据的专业法律意见。过失性解除、无过失解除、调岗、PIP、纪律处分和经济性裁员是否合法都依赖具体事实；企业享有正常用工管理权，工作量增加、调岗、绩效改进或纪律调查本身不当然违法。引用裁判用于说明审查方法，不代表相似案件必然得到相同结果。媒体采访中的前员工与新员工陈述用于补充事件背景，除官方通报或生效裁判明确确认的部分外，不应视为监管或法院已认定事实。",
