          "label": "关键事实",
          "html": "<p>网约车现行政策要求订单完成后，司机端列明乘客支付总金额、司机劳动报酬和本单抽成比例。聚合平台也应展示合作网约车平台及投诉渠道。<strong class=\"key\">这些透明要求仍然分散在各环节。</strong>本页核验的全国性规则没有规定跨平台订单“所有层级合并不得超过某一统一比例”的累计抽成上限，因此每个平台只展示自己这一层，仍可能留下总差额难以还原的问题。</p>"
