    "note": "<strong>把投诉目标写具体：</strong>“请核查订单【编号】在【时间】经过哪些主体、每层收取多少、司机端为何显示【金额】、适用哪版计价规则、动态价格受哪些因素影响，并保全相关日志。”比只说“抽成太高”更容易进入核查。",
