  "discussion": {
    "title": "“阳光抽成”还需要往接单前走一步。",
    "intro": "现行规则已经管到明码标价、动态定价、劳动报酬规则和事后抽成，但这些信息仍分散在交易的不同节点。",
    "html": "<p><strong>现行规则已经管到哪里：</strong>《互联网平台价格行为规则》要求动态定价公开规则和影响价格的因素、预估价公开构成、平台收费合理并公示；新就业形态劳动规则指引要求向劳动者公开订单分配、计件单价、抽成比例及其确定因素；网约车还有订单完成后的“乘客支付—司机报酬—本单抽成”展示。2026年货拉拉整改又进一步要求停止利用算法不合理压低货运价格，并常态化公示计价规则和运价涨降理由。</p><p><strong>目前仍有三个制度断层：</strong>本页核验的全国性规则中，尚未形成跨平台订单的统一累计抽成上限和全链路账单；也没有形成司机接单前必须同步看到消费者 / 货主端价格、接单后最低保障收入锁定的统一要求。《互联网平台价格行为规则》第五条虽然禁止平台强制平台内经营者降价，却对“基于平台商业模式由平台经营者实行统一定价”保留例外，因此经营者自主定价规则并不能自动解决网约车、货运中由平台统一报价和派单产生的压价问题。</p><p><strong>现行规则还没有单独列明“根据司机历史接受价个体化压低报价”：</strong>现行算法规则要求订单分配、报酬构成及支付等算法公平合理、公开透明，但本页核验的全国性规则尚未把“根据某个司机过去接过多低的价格、拒过多少单、等单多久，预测其最低接受价，再据此个体化压低报价”单独列成明确禁区。市场监管总局2026年的平台反垄断合规指引已经把具有市场支配地位的平台以不公平低价购买、利用画像和预测算法限定交易价格列为重要风险，这为进一步监管提供了方向。</p><p><strong>建议把接单前价格也纳入透明义务：</strong>把监管从“事后看抽成”推进到“接单前看价格形成”：建立最高有效抽成率或累计费率约束；消费者 / 货主端与司机端同步展示同一订单的需求端价格、平台及第三方费用、司机最低保障收入；跨平台转单合并计算全部平台费用；报价变化保留历史并说明是需求端加价、平台让利还是司机端调价；拒绝低价订单不应触发未来报价降低或派单惩罚。平台可以实行动态定价，但应让交易双方知道这一单的价格是怎样形成的。</p>"
  },
  "takeaway": "运输订单出现价格差时，把“用户付多少—订单经过谁—司机看到多少—每层收多少”对成一条账。",
